#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_palette_type_has_an_icon() {
        for (_, kinds) in crate::components::hot::PALETTE {
            for k in *kinds {
                let m = markup(k).unwrap_or_else(|| panic!("no icon for {k}"));
                assert!(m.contains("currentColor"), "{k}");
                assert!(!m.contains("id=") && !m.contains("<title"), "{k}: editor leftovers");
            }
        }
        assert_eq!(markup("OS::Octavia::Pool"), None);
    }
}
